<?php
declare(strict_types=1);session_start();
$base=__DIR__;foreach([$base.'/config/config.php',$base.'/config.php'] as $f){if(is_file($f)){require_once$f;break;}}require_once$base.'/includes/expediente360_helpers.php';
if(!isset($pdo)||!($pdo instanceof PDO)){http_response_code(500);exit('PDO no disponible.');}
$id=(int)($_GET['id']??$_POST['actividad_id']??0);$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$r=e360_register_attendee($pdo,$id,(string)($_POST['cedula']??''),(string)($_POST['telefono']??''),(string)($_POST['nombre']??''));$msg='Asistente registrado: '.$r['nombre'].' · '.$r['clasificacion'];}
 catch(Throwable$e){$err=$e->getMessage();}
}
$q=$pdo->prepare('SELECT * FROM actividades WHERE id=?');$q->execute([$id]);$a=$q->fetch(PDO::FETCH_ASSOC);if(!$a){http_response_code(404);exit('Actividad no encontrada.');}
$q=$pdo->prepare("SELECT COUNT(*) FROM actividad_asistencias WHERE actividad_id=? AND asistencia='asistio'");$q->execute([$id]);$total=(int)$q->fetchColumn();$meta=(int)($a['meta_asistencia']??0);$faltan=max(0,$meta-$total);$extra=max(0,$total-$meta);
$q=$pdo->prepare("SELECT aa.*,p.clasificacion_actual FROM actividad_asistencias aa LEFT JOIN personas p ON p.id=aa.persona_id WHERE aa.actividad_id=? AND aa.asistencia='asistio' ORDER BY aa.id DESC LIMIT 250");$q->execute([$id]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registrar asistentes</title><style>:root{--o:#f28c18;--nav:#101a2e;--bg:#f3f5f9;--mut:#6f7787}*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial;background:var(--bg);color:#172033}.top{background:var(--nav);color:#fff;padding:22px}.wrap{max-width:1180px;margin:auto;padding:22px}.hero{background:linear-gradient(135deg,#fff7ed,#fff);border:1px solid #f6d5af;border-radius:24px;padding:24px;margin-top:-42px;box-shadow:0 18px 45px #13213a16}.hero h1{margin:4px 0}.grid{display:grid;grid-template-columns:1fr 1.6fr;gap:18px;margin-top:18px}.card{background:#fff;border-radius:20px;padding:20px;box-shadow:0 12px 34px #1720330d}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:16px 0}.stat{padding:16px;border-radius:16px;background:#f7f8fb}.stat b{display:block;font-size:26px}.ok{background:#eafff2;color:#13753c;padding:12px;border-radius:12px}.err{background:#fff0f0;color:#a22525;padding:12px;border-radius:12px}.field{margin:12px 0}.field label{display:block;font-weight:800;margin-bottom:6px}.field input{width:100%;padding:14px;border:1px solid #d9deea;border-radius:12px;font-size:16px}.btn{width:100%;padding:14px;background:var(--o);border:0;border-radius:12px;color:#fff;font-weight:900}.row{display:grid;grid-template-columns:1fr 1.2fr 1fr .8fr;gap:10px;padding:12px 0;border-bottom:1px solid #edf0f5}.pill{display:inline-block;padding:5px 9px;border-radius:999px;font-size:12px;font-weight:900}.act{background:#fff0dc;color:#a85c00}.sim{background:#e8f3ff;color:#155b9a}.green{color:#167744}.yellow{color:#a86b00}@media(max-width:800px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.row{grid-template-columns:1fr}.row.head{display:none}.hero{margin-top:-22px}.wrap{padding:14px}.card{padding:16px}.top{padding:18px 14px}}</style></head><body><div class="top"><div class="wrap"><strong>VPNACIONAL · ACTIVIDADES</strong></div></div><main class="wrap"><section class="hero"><small><?=htmlspecialchars($a['estado']??'')?> · <?=htmlspecialchars($a['municipio']??'')?> · <?=htmlspecialchars($a['parroquia']??'')?></small><h1><?=htmlspecialchars($a['titulo'])?></h1><p>Registra únicamente cédula y teléfono. El nombre y todos los datos electorales se consultan y almacenan desde el servidor.</p><div class="stats"><div class="stat"><span>Declarados</span><b><?=$meta?></b></div><div class="stat"><span>Registrados</span><b><?=$total?></b></div><div class="stat"><span>Faltan</span><b class="<?=$faltan?'yellow':'green'?>"><?=$faltan?></b></div><div class="stat"><span>Adicionales</span><b><?=$extra?></b></div></div></section><div class="grid"><section class="card"><h2>Nuevo asistente</h2><?php if($msg):?><div class="ok"><?=htmlspecialchars($msg)?></div><?php endif;?><?php if($err):?><div class="err"><?=htmlspecialchars($err)?></div><?php endif;?><form method="post" autocomplete="off"><input type="hidden" name="actividad_id" value="<?=$id?>"><div class="field"><label>Cédula</label><input name="cedula" inputmode="numeric" required placeholder="Ej. 12345678"></div><div class="field"><label>Nombre y apellido</label><input name="nombre" placeholder="Solo se habilita si no aparece en REP"></div><div class="field"><label>Teléfono</label><input name="telefono" inputmode="tel" required placeholder="0414 0000000"></div><button class="btn">Registrar asistencia</button></form><p style="color:var(--mut);font-size:13px">Se permite superar la cantidad declarada. Los registros adicionales quedarán identificados sin bloquear la actividad.</p></section><section class="card"><h2>Asistentes registrados</h2><div class="row head"><b>Cédula</b><b>Nombre</b><b>Teléfono</b><b>Clasificación</b></div><?php foreach($rows as$r):$cl=$r['clasificacion_actual']?:$r['clasificacion_asistente'];?><div class="row"><span><?=htmlspecialchars($r['cedula'])?></span><strong><?=htmlspecialchars($r['nombre'])?></strong><span><?=htmlspecialchars($r['telefono_reportado']?:$r['telefono'])?></span><span><i class="pill <?=$cl==='ACTIVISTA'?'act':'sim'?>"><?=htmlspecialchars($cl?:'SIMPATIZANTE')?></i><?php if(!empty($r['es_adicional'])):?><br><small>Adicional</small><?php endif;?></span></div><?php endforeach;?><?php if(!$rows):?><p>No hay asistentes registrados.</p><?php endif;?></section></div></main></body></html>